<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE']);$db=Database::connection();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=(string)($_POST['statut']??'');if(in_array($status,['a_recevoir','facturee','payee','annulee'],true)){$db->prepare('UPDATE commissions SET statut=?,date_paiement=IF(?="payee",CURRENT_DATE,NULL) WHERE id=?')->execute([$status,$status,$id]);audit('STATUT_COMMISSION','commission',$id,$status);}redirect('commissions/index.php');}$rows=$db->query("SELECT cm.*,c.numero_police,p.nom produit,co.raison_sociale compagnie FROM commissions cm JOIN contrats c ON c.id=cm.contrat_id JOIN souscriptions s ON s.id=c.souscription_id JOIN offres_devis o ON o.id=s.offre_id JOIN produits_assurance p ON p.id=o.produit_id JOIN compagnies co ON co.id=p.compagnie_id ORDER BY cm.date_exigibilite DESC")->fetchAll();$total=array_sum(array_map(fn($r)=>(float)$r['montant'],$rows));$title='Commissions';require __DIR__.'/../../includes/header.php';?>
<div class="page-heading"><div><h1 class="h3">Commissions</h1><p class="text-secondary">Total : <?= number_format($total,0,',',' ') ?> FCFA</p></div><a class="btn btn-primary" href="baremes.php">Gérer les barèmes</a></div><div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Police</th><th>Compagnie / produit</th><th>Base</th><th>Taux</th><th>Commission</th><th>Statut</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['numero_police']) ?></td><td><?= e($r['compagnie']) ?><div class="small"><?= e($r['produit']) ?></div></td><td><?= number_format((float)$r['base_calcul'],0,',',' ') ?></td><td><?= e((string)$r['taux_applique']) ?> %</td><td><strong><?= number_format((float)$r['montant'],0,',',' ') ?> FCFA</strong></td><td><?= e($r['statut']) ?></td><td><form method="post" class="d-flex gap-1"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $r['id'] ?>"><select name="statut" class="form-select form-select-sm"><?php foreach(['a_recevoir','facturee','payee','annulee'] as $st): ?><option <?= $r['statut']===$st?'selected':'' ?>><?= $st ?></option><?php endforeach ?></select><button class="btn btn-sm btn-outline-primary">OK</button></form></td></tr><?php endforeach ?></tbody></table></div></div><?php require __DIR__.'/../../includes/footer.php'; ?>
